"""Alternative LiveArea backgrounds for VCMI-Vita (840x500). CC0, generated by code.
Reuses helpers from make_vcmi_livearea.py. Usage: python make_bg_variants.py --out dir"""
import argparse, math, os, random, sys
import numpy as np
from PIL import Image, ImageDraw, ImageFilter
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
import make_vcmi_livearea as M
from make_vcmi_livearea import SS, vgrad, radial, to_pil, from_pil, ridge, hexc, draw_castle, pine, mist

W, H = 840, 500


def layer(a, w, h, rdg, top, bot, glow, rim, rim_col):
    yy = np.arange(h, dtype=np.float32)[:, None]
    r = rdg[None, :].astype(np.float32)
    t = np.clip((yy - r) / (0.30 * h), 0, 1)[..., None]
    col = np.array(hexc(top), np.float32) * (1 - t) + np.array(hexc(bot), np.float32) * t
    alpha = np.clip((yy - r) / (1.2 * SS) + 0.5, 0, 1)[..., None]
    if rim > 0:
        edge = np.clip(1 - np.abs(yy - r - 1.5 * SS) / (2.2 * SS), 0, 1)[..., None]
        gx = glow[np.clip(rdg.astype(int), 0, h - 1), np.arange(w)][None, :, None]
        col = col + edge * gx * np.array(rim_col, np.float32) * rim
    return a * (1 - alpha) + col * alpha


def stars(base, rnd, w, h, n, limit=0.55, sparkle=True):
    st = Image.new('RGBA', (w, h), (0, 0, 0, 0))
    d = ImageDraw.Draw(st)
    for _ in range(n):
        x = rnd.random() * w
        y = (rnd.random() ** 1.7) * limit * h
        b = int(255 * rnd.uniform(0.35, 1.0) * max(0.0, 1 - y / (limit * 1.15 * h)))
        r = rnd.choice([0.5, 0.5, 0.7, 1.0, 1.4]) * SS
        d.ellipse([x - r, y - r, x + r, y + r], fill=(255, 244, 220, b))
    if sparkle:
        for _ in range(5):
            x = rnd.uniform(0.05, 0.95) * w
            y = rnd.uniform(0.04, 0.28) * h
            L = rnd.uniform(5, 9) * SS
            d.line([(x - L, y), (x + L, y)], fill=(255, 244, 220, 110), width=max(1, SS // 2))
            d.line([(x, y - L), (x, y + L)], fill=(255, 244, 220, 110), width=max(1, SS // 2))
    return Image.alpha_composite(base.convert('RGBA'), st)


def finish(a, w, h, vig=0.30):
    yy, xx = np.mgrid[0:h, 0:w].astype(np.float32)
    v = np.clip(((xx - w / 2) / (w / 2)) ** 2 + ((yy - h / 2) / (h / 2)) ** 2, 0, 1.4)
    a = a * (1 - vig * v)[..., None]
    return to_pil(a).resize((W, H), Image.LANCZOS)


def trees(im, rnd, w, h, col=(6, 11, 24, 255), n=14):
    d = ImageDraw.Draw(im)
    for _ in range(n):
        pine(d, rnd.uniform(-0.01, 0.20) * w, h * rnd.uniform(0.99, 1.06), h * rnd.uniform(0.14, 0.34), col)
    for _ in range(n - 2):
        pine(d, rnd.uniform(0.84, 1.01) * w, h * rnd.uniform(0.99, 1.06), h * rnd.uniform(0.12, 0.28), col)
    return im


def landscape(seed, sky, glow_col, glow_pos, layers, rim_col, castle_x=None, castle_layer=2,
              castle_col='#0b1630', window=(255, 196, 108), moon=None, mist_col='#a9bcdc',
              star_n=300, pines=True, glow_amt=0.5, extra=None):
    w, h = W * SS, H * SS
    rnd = random.Random(seed)
    a = vgrad(w, h, sky)
    glow = radial(w, h, glow_pos[0] * w, glow_pos[1] * h, 0.62 * w, 0.64 * h, 2.0)
    a += glow[..., None] * np.array(glow_col, np.float32) * glow_amt
    im = stars(to_pil(a), rnd, w, h, star_n)
    if moon:
        mx, my, mr = moon
        mg = radial(w, h, mx * w, my * h, 0.22 * w, 0.22 * w, 2.0)
        arr = from_pil(im) + mg[..., None] * np.array([190, 210, 255], np.float32) * 0.55
        im = to_pil(arr).convert('RGBA')
        d = ImageDraw.Draw(im)
        r = mr * h
        d.ellipse([mx * w - r, my * h - r, mx * w + r, my * h + r], fill=(246, 244, 232, 255))
        d.ellipse([mx * w - r * 0.35 - r * 0.25, my * h - r * 0.25, mx * w - r * 0.35 + r * 0.25, my * h + r * 0.25], fill=(232, 230, 218, 255))
    a = from_pil(im)
    for i, (bs, am, jg, ct, cb, rm) in enumerate(layers):
        rd = ridge(w, h, bs, am, seed + 17 * i, jg)
        a = layer(a, w, h, rd, ct, cb, glow, rm, rim_col)
        if castle_x is not None and i == castle_layer:
            img = to_pil(a)
            cx = int(castle_x * w)
            u = h / 100.0 * 0.92
            wm = Image.new('L', (w, h), 0)
            draw_castle(img, cx, rd[cx] + 3 * u, u, hexc(castle_col), wm)
            arr = from_pil(img)
            wg = np.asarray(wm.filter(ImageFilter.GaussianBlur(2.6 * SS)), np.float32) / 255.0
            arr += wg[..., None] * np.array(window, np.float32) * 1.4
            sharp = (np.asarray(wm, np.float32) / 255.0)[..., None]
            a = arr * (1 - sharp) + np.array([255, 214, 130], np.float32) * sharp
            a = mist(a, w, h, 0.79, 0.20, mist_col)
        elif i == 1:
            a = mist(a, w, h, 0.69, 0.20, mist_col)
        elif i == 3:
            a = mist(a, w, h, 0.885, 0.20, mist_col)
    fg = to_pil(a).convert('RGBA')
    if pines:
        fg = trees(fg, rnd, w, h)
    if extra:
        fg = extra(fg, w, h, rnd)
    return finish(from_pil(fg), w, h)


def v_dawn():  # warm golden sunrise
    return landscape(21, [(0, '#0d1a3c'), (0.30, '#2a3f78'), (0.55, '#7a6a98'), (0.72, '#e0907a'), (0.86, '#f6b777'), (1, '#fcdc9a')],
                     (255, 190, 115), (0.52, 0.74),
                     [(0.58, 0.09, 0.55, '#8a7aa8', '#b08aa0', 0.7), (0.65, 0.085, 0.45, '#5f6a98', '#7d78a0', 0.55),
                      (0.73, 0.075, 0.35, '#3a4f7e', '#4a5a86', 0.4), (0.82, 0.06, 0.25, '#1d3157', '#17294a', 0.25),
                      (0.92, 0.035, 0.10, '#0b1630', '#08101f', 0.0)],
                     (255, 196, 120), castle_x=0.20, star_n=120, mist_col='#e2b9b0', glow_amt=0.62)


def v_moon():  # cold moonlit snowy peaks
    return landscape(33, [(0, '#040813'), (0.30, '#0c1a3a'), (0.60, '#1d3a6c'), (0.85, '#3c5f94'), (1, '#6f8fb8')],
                     (150, 190, 255), (0.30, 0.55),
                     [(0.52, 0.12, 0.75, '#b9c9e6', '#8da2c8', 0.6), (0.62, 0.10, 0.65, '#7c92bb', '#5f78a4', 0.5),
                      (0.72, 0.08, 0.45, '#40598a', '#30487a', 0.35), (0.82, 0.06, 0.25, '#1a2f55', '#14264a', 0.2),
                      (0.92, 0.035, 0.10, '#0a1430', '#070e20', 0.0)],
                     (170, 205, 255), castle_x=0.80, moon=(0.17, 0.20, 0.07), mist_col='#b5c8e8', glow_amt=0.45, star_n=360)


def v_forest():  # teal misty twilight, no castle, lots of pines
    return landscape(47, [(0, '#07121c'), (0.35, '#0f2c40'), (0.62, '#1f5a66'), (0.82, '#5c9a8a'), (1, '#c8c88a')],
                     (240, 215, 140), (0.50, 0.78),
                     [(0.58, 0.09, 0.55, '#4b8a8a', '#6a9a90', 0.45), (0.66, 0.085, 0.45, '#2f6c74', '#44808a', 0.35),
                      (0.75, 0.07, 0.35, '#1c4a58', '#18404e', 0.25), (0.84, 0.055, 0.25, '#0f2c3c', '#0b2230', 0.1),
                      (0.93, 0.03, 0.10, '#06131f', '#040c16', 0.0)],
                     (240, 215, 140), castle_x=None, mist_col='#a8d0c4', glow_amt=0.5, star_n=200)


def v_emblem():  # abstract: night gradient + compass rings + gold constellation lines
    w, h = W * SS, H * SS
    rnd = random.Random(5)
    a = vgrad(w, h, [(0, '#050a18'), (0.5, '#0f1f44'), (1, '#1b3566')])
    g = radial(w, h, 0.5 * w, 0.5 * h, 0.75 * w, 0.95 * h, 1.6)
    a += g[..., None] * np.array([70, 110, 190], np.float32) * 0.5
    im = stars(to_pil(a), rnd, w, h, 380, limit=1.0, sparkle=False)
    d = ImageDraw.Draw(im)
    cx, cy = 0.5 * w, 0.5 * h
    for k, (rr, wd, al) in enumerate([(0.62, 1.4, 90), (0.50, 1.0, 70), (0.74, 1.0, 55), (0.88, 1.0, 40)]):
        r = rr * h
        d.ellipse([cx - r, cy - r, cx + r, cy + r], outline=(214, 172, 84, al), width=int(wd * SS))
    for i in range(32):  # compass ticks on the main ring
        ang = i * math.pi / 16
        r0, r1 = 0.62 * h, (0.67 if i % 4 == 0 else 0.645) * h
        d.line([(cx + r0 * math.cos(ang), cy + r0 * math.sin(ang)), (cx + r1 * math.cos(ang), cy + r1 * math.sin(ang))],
               fill=(214, 172, 84, 110), width=int(1.2 * SS))
    for ang in (-math.pi / 2, 0, math.pi / 2, math.pi):  # four long compass points
        r0, r1 = 0.50 * h, 1.0 * h
        d.line([(cx + r0 * math.cos(ang), cy + r0 * math.sin(ang)), (cx + r1 * math.cos(ang) * 1.6, cy + r1 * math.sin(ang))],
               fill=(214, 172, 84, 50), width=int(1.0 * SS))
    pts = [(0.10, 0.30), (0.18, 0.18), (0.27, 0.34), (0.34, 0.14), (0.05, 0.62), (0.13, 0.78), (0.24, 0.70)]
    pts += [(1 - x, y) for x, y in [(0.12, 0.26), (0.22, 0.12), (0.30, 0.30), (0.08, 0.70), (0.19, 0.84), (0.28, 0.66)]]
    segs = [(0, 1), (1, 2), (2, 3), (4, 5), (5, 6), (7, 8), (8, 9), (10, 11), (11, 12)]
    P = [(x * w, y * h) for x, y in pts]
    for s, e in segs:
        d.line([P[s], P[e]], fill=(214, 172, 84, 90), width=int(1.0 * SS))
    for x, y in P:
        r = 2.6 * SS
        d.ellipse([x - r, y - r, x + r, y + r], fill=(255, 232, 170, 255))
    return finish(from_pil(im), w, h, vig=0.35)


VARIANTS = {'bg_a_dawn': v_dawn, 'bg_b_moonlit': v_moon, 'bg_c_forest': v_forest, 'bg_d_compass': v_emblem}


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument('--out', default='bg_variants')
    args = ap.parse_args()
    os.makedirs(args.out, exist_ok=True)
    for name, fn in VARIANTS.items():
        M.save_png8(fn(), os.path.join(args.out, name + '.png'))


if __name__ == '__main__':
    main()
